                });
            } else { candidatesListEl.innerHTML = '<p class="placeholder-text">无可用候选人</p>'; }

            const companionsListEl = document.getElementById('companions-list');
            companionsListEl.innerHTML = '';
            const companionsValue = SafeGetValue(statData, '世界.当前在场角色', []);
            const companionsOnSite = ParseArrayValue(companionsValue, []);
            if (companionsOnSite.length === 0 || (companionsOnSite.length === 1 && companionsOnSite[0] === '')) {
                companionsListEl.innerHTML = '<p class="placeholder-text">公寓很安静...</p>';
            } else {
                companionsOnSite.forEach(name => {
                    if(typeof name !== 'string' || name === "") return;
                    const affectionVal = SafeGetValue(statData, `${name}.好感度`, 0);
                    const debtVal = SafeGetValue(statData, `${name}.债务`, 0);
                    const memoriesValue = SafeGetValue(statData, `${name}.关键记忆`, []);
                    const memories = ParseArrayValue(memoriesValue, []);
                    const statusValue = SafeGetValue(statData, `${name}.状态`, []);
                    const statusArray = ParseArrayValue(statusValue, []);
                    const statusTags = statusArray.join(', ') || '无';
                    const affectionStages = [ { min: -100, max: -51, name: '憎恶', color: '#b91c1c' }, { min: -50, max: -11, name: '屈辱', color: 'var(--accent-red)' }, { min: -10, max: 10, name: '交易', color: 'var(--accent-yellow)' }, { min: 11, max: 40, name: '好奇', color: '#6ee7b7' }, { min: 41, max: 70, name: '友好', color: 'var(--accent-green)' }, { min: 71, max: 100, name: '爱慕', color: 'var(--accent-pink)' } ];
                    const memoriesHtml = (memories.length > 0) ? `<ul>${memories.map(mem => `<li><i class="fas fa-key" style="margin-right: 5px; opacity: 0.6;"></i>${mem}</li>`).join('')}</ul>` : '<p style="font-size:0.85rem;color:var(--text-secondary);padding: 4px 0;">无</p>';
                    const aVal = parseFloat(affectionVal) || 0;
                    const stage = affectionStages.find(s => aVal >= s.min && s.max >= aVal) || { name: '未知', color: 'var(--panel-border)' };
                    const percentage = (Math.max(-100, Math.min(100, aVal)) + 100) / 2;
                    companionsListEl.innerHTML += `<div class="companion-card"><div class="companion-header"><span class="companion-name">${name}</span><span class="companion-status-tags">${statusTags}</span></div><div class="property"><div class="property-name">好感度</div><div class="property-value" style="color: ${stage.color};">${aVal} (${stage.name})</div><div class="progress-bar-container"><div class="progress-bar-value" style="width: ${percentage}%; background-color: ${stage.color};"></div></div></div><div class="property"><div class="property-name">剩余债务</div><div class="property-value">¥ ${new Intl.NumberFormat().format(debtVal)}</div></div><div class="key-memories"><div class="property-name" style="margin-bottom: 5px;">关键记忆</div>${memoriesHtml}</div></div>`;
                });
            }

            const theaterContentEl = document.getElementById('theater-content');
            const theaterText = SafeGetValue(statData, '世界.小剧场内容', '...');
            theaterContentEl.textContent = (theaterText === '...' || !theaterText) ? '...' : String(theaterText);

            const messageContentEl = document.getElementById('message-content');
            messageContentEl.innerHTML = '';
            const messagesValue = SafeGetValue(statData, '世界.简讯内容', []);
            const instantMessages = ParseArrayValue(messagesValue, []);
            if (instantMessages.length > 0) {
                instantMessages.forEach(msg => {
                    if(msg && typeof msg === 'object' && msg.from && msg.text) {
                        messageContentEl.innerHTML += `<div class="message-bubble"><div class="message-from">${msg.from}</div><div class="message-text">${msg.text}</div></div>`;
                     }
                });
            } else { messageContentEl.innerHTML = '<p class="placeholder-text">暂无新消息</p>'; }

        } catch (error) {
            console.error("状态栏加载出错:", error);
            const container = document.querySelector('.status-panel-container');
            if(container) container.innerHTML = `<div style="color:red; padding:20px; font-family:monospace;"><b>状态栏加载出错:</b> ${error.message}<br><hr><pre style="white-space: pre-wrap;">${error.stack}</pre></div>`;
        }
    }

    $(() => {
        initDisplay();
    });
</script>
</body>
</html>
